import type { ConfigRow, Register } from 'claude-code'
import { film } from './film'

// Shared by every film plugin: scripts/build.mjs copies this file next to each plugin's film.ts.
// Everything here stays dormant unless that film's theme is the one picked in /theme.

export type Fx = {
  kind: 'rain' | 'snow' | 'rise' | 'twinkle' | 'drift'
  glyphs: string
  colors: string[] // brightest first
  density: number // share of the band's cells lit at once
}
export type Film = { slug: string; title: string; verbs: string[]; done: string[]; hint: string; fx: Fx }

const THEME = `custom:${film.slug}:${film.slug}`
const ROWS = 3
const TICK_MS = 110

type Particle = { x: number; y: number; dx: number; dy: number; trail: number; age: number; life: number; tone: number; g: string }
export type Run = { tone: number; text: string } // tone -1 is blank

const rand = (n: number) => Math.floor(Math.random() * n)
const pick = <T,>(xs: readonly T[]): T => xs[rand(xs.length)]!

// A particle field the size of the band. Each kind is a spawn rule; a particle moves by (dx, dy)
// per tick, drags `trail` dimmer cells behind it, and twinkles fade in and out over their life.
export const createFx = (fx: Fx) => {
  const glyphs = [...fx.glyphs]
  const last = fx.colors.length - 1
  let ps: Particle[] = []
  let width = 0

  const spawn = (): Particle => {
    const p = { age: 0, life: Infinity, trail: 0, tone: 0, dx: 0, dy: 0, g: pick(glyphs) }
    const drift = (Math.random() - 0.5) * 0.3
    switch (fx.kind) {
      case 'rain': return { ...p, x: rand(width), y: -rand(6), dy: 1, trail: last }
      case 'snow': return { ...p, x: rand(width), y: 0, dx: drift, dy: 0.2 + Math.random() * 0.25, tone: rand(last + 1) }
      case 'rise': return { ...p, x: rand(width), y: ROWS - 1, dx: drift, dy: -(0.2 + Math.random() * 0.3), tone: rand(last + 1) }
      case 'drift': return { ...p, x: 0, y: rand(ROWS), dx: 0.8 + Math.random() * 1.6, trail: Math.min(3, last) }
      case 'twinkle': return { ...p, x: rand(width), y: rand(ROWS), life: 6 + rand(10) }
    }
  }

  const alive = (p: Particle) =>
    p.age < p.life &&
    p.x - (p.dx > 0 ? p.trail : 0) < width && p.x > -1 &&
    p.y - (p.dy > 0 ? p.trail : 0) < ROWS && p.y > -7 && !(p.dy < 0 && p.y < -0.5)

  const step = (columns: number) => {
    width = columns
    for (const p of ps) { p.x += p.dx; p.y += p.dy; p.age += 1 }
    ps = ps.filter(alive)
    const want = Math.round(fx.density * width * ROWS)
    for (let n = Math.min(want - ps.length, Math.ceil(want / 6) + 1); n > 0; n--) ps.push(spawn())
  }

  const frame = (): Run[][] => {
    const grid: ({ tone: number; g: string } | undefined)[][] = Array.from({ length: ROWS }, () => Array(width).fill(undefined))
    const put = (x: number, y: number, tone: number, g: string) => {
      const cx = Math.round(x), cy = Math.round(y)
      const row = grid[cy]
      if (!row || cx < 0 || cx >= width) return
      if (!row[cx] || tone < row[cx]!.tone) row[cx] = { tone, g }
    }
    const glyph = (p: Particle) => (fx.kind === 'rain' ? pick(glyphs) : p.g) // rain flickers
    for (const p of ps) {
      const tone = fx.kind === 'twinkle' ? Math.round(Math.abs(1 - (2 * p.age) / p.life) * last) : p.tone
      put(p.x, p.y, tone, glyph(p))
      for (let k = 1; k <= p.trail; k++) put(p.x - k * Math.sign(p.dx), p.y - k * Math.sign(p.dy), Math.min(last, tone + k), glyph(p))
    }
    return grid.map(row => {
      const runs: Run[] = []
      for (const cell of row) {
        const tone = cell?.tone ?? -1
        const ch = cell?.g ?? ' '
        const prev = runs[runs.length - 1]
        if (prev?.tone === tone) prev.text += ch
        else runs.push({ tone, text: ch })
      }
      return runs
    })
  }

  return { step, frame, width: () => width }
}

const isOurs = (rows: readonly ConfigRow[]) => rows.find(row => row.key === 'theme')?.value === THEME

export const register: Register = on => {
  const fx = createFx(film.fx)
  let active: boolean | undefined // is this film's theme the one picked in /theme
  let ambient = false // /<slug> keeps the animation on while Claude is idle
  let verb: string | undefined
  let columns = 80
  let timer: { cancel: () => void } | undefined

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: film.slug, description: `${film.title} theme: toggle its animation while Claude is idle` })
    active = isOurs(await $.config.list())
    return next(e)
  })

  // /theme can change between turns; re-read it once per prompt, and on every change made through /config.
  on('prompt.submit', async ($, e, next) => {
    verb = pick(film.verbs)
    try { active = isOurs(await $.config.list()) } catch { /* keep the last answer */ }
    return next(e)
  }).catch(($, e, next) => next(e)) // a theme never stands between you and your prompt

  on('config.set', { key: 'theme' }, async ($, e, next) => {
    const result = await next(e)
    if (!result.deny) active = result.value === THEME
    $.ui.invalidate('ui.render')
    return result
  }).catch(($, e, next) => next(e))

  on('command.run', { command: film.slug }, async $ => {
    active ??= isOurs(await $.config.list())
    if (!active) return { text: `Pick "${film.title}" in /theme first, then run /${film.slug} again.` }
    ambient = !ambient
    $.ui.invalidate('ui.render')
    return { text: ambient ? `${film.title}: animation stays on while idle.` : `${film.title}: animation only while Claude works.` }
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    active ??= isOurs(await $.config.list())
    return active ? next({ ...e, props: { ...e.props, word: (verb ??= pick(film.verbs)) } }) : next(e)
  })

  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => {
    active ??= isOurs(await $.config.list())
    return active ? next({ ...e, props: { ...e.props, word: film.done[e.props.durationMs % film.done.length]! } }) : next(e)
  })

  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    active ??= isOurs(await $.config.list())
    const quiet = !active || e.props.isWorking || e.props.isDraft
    return quiet ? next(e) : next({ ...e, props: { ...e.props, tail: `· ${film.hint}` } })
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    active ??= isOurs(await $.config.list())
    if (!active || !(e.props.isWorking || ambient) || e.props.hasSurvey) {
      timer?.cancel()
      timer = undefined
      return next(e)
    }
    columns = e.props.bodyColumns
    if (fx.width() !== columns) for (let i = 0; i < 30; i++) fx.step(columns) // first frame and resizes start mid-motion
    timer ??= $.clock.every(TICK_MS, () => {
      fx.step(columns)
      $.ui.invalidate('ui.render')
    })

    const { Box, Text } = $.ui.resolve(e)
    const colors = film.fx.colors
    return (
      <Box flexDirection="column">
        {fx.frame().map(runs => (
          <Text wrap="truncate">
            {runs.map(run =>
              run.tone < 0 ? run.text : <Text color={colors[run.tone]} weight={run.tone === 0 ? 'bold' : 'regular'}>{run.text}</Text>)}
          </Text>
        ))}
      </Box>
    )
  })
}
